package com.sathavahana.kalamkari.service;
import com.sathavahana.kalamkari.domain.*; import com.sathavahana.kalamkari.payment.*; import com.sathavahana.kalamkari.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.util.*;
@Service public class PaymentService {private final PaymentRepository payments; private final PaymentPort provider; public PaymentService(PaymentRepository p,PaymentPort x){payments=p;provider=x;} @Transactional public Payment pay(Order o,String method,String key){if(key==null||key.isBlank())throw new IllegalArgumentException("Idempotency-Key is required");var old=payments.findByIdempotencyKey(key);if(old.isPresent())return old.get();var p=new Payment(o,method, o.getTotalAmount(),key);if("COD".equalsIgnoreCase(method)){p.setStatus("AUTHORIZED");o.setPaymentStatus("AUTHORIZED");}else{o.setPaymentStatus("PENDING");p.setStatus("PENDING");}return payments.save(p);} public Payment capture(Long orderId){var p=payments.findByOrderId(orderId).orElseThrow();p.setStatus("CAPTURED");return payments.save(p);} }
